import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Multi-shot resume for handle effects — design + tree-walk prototype","description":"","frontmatter":{"title":"Multi-shot `resume` for `handle` effects — design + tree-walk prototype","type":"design","date":"2026-10-26T00:00:00.000Z","refs":["ADR-0158","ADR-0106"]},"headers":[],"relativePath":"handl/project/design/multishot-resume.md","filePath":"vendored/handl/project/design/multishot-resume.md"}'),a={name:`handl/project/design/multishot-resume.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="multi-shot-resume-for-handle-effects-—-design-tree-walk-prototype" tabindex="-1">Multi-shot <code>resume</code> for <code>handle</code> effects — design + tree-walk prototype <a class="header-anchor" href="#multi-shot-resume-for-handle-effects-—-design-tree-walk-prototype" aria-label="Permalink to “Multi-shot resume for handle effects — design + tree-walk prototype”">​</a></h1><p><strong>Refs</strong>: ADR-0158 (resumption semantics — <code>perform</code> dispatches in-flight), ADR-0106 (self-contained arrow values), ADR-0076 (<code>handle</code> dynamic extent), Sanada — <em>Algebraic effects and handlers for arrows</em>.</p><h2 id="the-feature" tabindex="-1">The feature <a class="header-anchor" href="#the-feature" aria-label="Permalink to “The feature”">​</a></h2><p>Handler clauses may take a second parameter — the <strong>resumption</strong>:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handle f with {</span></span>
<span class="line"><span>  choose: (opts, resume) ~&gt; list.flat_map(opts, (o) ~&gt; resume(o))</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>resume(x)</code> feeds <code>x</code> back as the <code>perform</code>&#39;s result and continues the handled body from the op site. Calling it more than once runs the continuation per call — nondeterminism (<code>choose</code>), generators (<code>yield</code>), backtracking.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>ADR-0158 made <code>perform</code> dispatch in-flight (one-shot): <code>h[op](arg)</code>&#39;s return value is the <code>perform</code> result — &quot;resume&quot; is the call returning. A <code>resume</code> <strong>value</strong> reifies &quot;the rest of the body&#39;s evaluation&quot; as a callable — a delimited continuation. In the tree-walk engine (<code>hnl-engine-exec-tree-walk</code>) the continuation at a <code>perform</code> site is the Rust call stack inside <code>eval_inner_td</code> — not a value.</p><p>Reification options considered:</p><table tabindex="0"><thead><tr><th>Option</th><th>Verdict</th></tr></thead><tbody><tr><td><strong>(a) CPS the eval at perform sites</strong></td><td>Rejected — <code>eval_inner_td</code> is a non-CPS recursive interpreter over <code>TermData</code>; CPS&#39;ing every <code>Seq</code>/<code>Choice</code>/<code>App</code>/<code>Op</code> arm is a full-eval rewrite, and it would not survive host-callback boundaries (<code>TreeWalkCallable</code> re-enters on a fresh engine).</td></tr><tr><td><strong>(b) Coroutine/generator for the body</strong></td><td>Rejected — a stackful coroutine (thread or <code>gen</code>) resumes <strong>once</strong>; multi-shot needs <em>copyable</em> continuations. Stable Rust has no <code>gen</code>, and engine state (<code>&amp;Ast</code>, <code>&amp;mut ScopeStack</code>) is borrowed, not <code>Send</code>.</td></tr><tr><td><strong>(c) Delimited re-run (replay journal)</strong></td><td><strong>Chosen.</strong> <code>resume(x)</code> re-evaluates the body term from the <code>handle</code> boundary, replaying recorded op results up to the suspension index and feeding <code>x</code> at that index. Copyable by construction — every <code>resume</code> call gets a fresh run. Works today, no eval rewrite.</td></tr><tr><td><strong>(d) Closure over <code>eval(remaining_term, env)</code></strong></td><td>Rejected — eval is not compositional at perform sites: <code>Seq</code> recurses into <code>fst</code>/<code>snd</code> inside the same Rust frame; there is no &quot;next node pointer&quot; to close over.</td></tr></tbody></table><h2 id="why-replay-fits-this-engine" tabindex="-1">Why replay fits this engine <a class="header-anchor" href="#why-replay-fits-this-engine" aria-label="Permalink to “Why replay fits this engine”">​</a></h2><ul><li><strong>Arrows are self-contained data</strong> (ADR-0106): a body&#39;s <code>TermData</code>, the <code>incoming</code> value, the handler value, and the <code>Ast</code> arena are all serializable data — no process-local frame references.</li><li><strong><code>ScopeStack</code> is clonable</strong>: the entry environment at the <code>handle</code> boundary is a snapshot (<code>scopes</code> + <code>captured</code> + shared <code>globals</code> Rc).</li><li><strong>Ops are already data</strong>: <code>perform</code> mints <code>IO&lt;{op: arg}&gt;</code> values; the journal only has to record the <em>result fed back</em> per suspension point.</li><li><strong>Suspension = the existing error channel</strong>: <code>LangError::Suspended{id}</code> unwinds to the nearest journal driver; <code>RefCell</code> borrows drop cleanly on <code>Result</code> propagation (unlike <code>catch_unwind</code>, which the <code>stacker::maybe_grow</code> seams would abort on — panics cannot unwind through <code>psm::on_stack</code>&#39;s <code>extern &quot;C&quot;</code> boundary).</li></ul><h2 id="semantics" tabindex="-1">Semantics <a class="header-anchor" href="#semantics" aria-label="Permalink to “Semantics”">​</a></h2><p>Clause arity selects the mode; both forms desugar to the same driver:</p><ul><li><strong>One-shot</strong> <code>op: x ~&gt; e</code> — today&#39;s direct-style dispatch. Equivalent to <code>(x, k) ~&gt; k(e)</code>: the clause result feeds back at the <code>perform</code> site and the body continues. Unchanged code path.</li><li><strong>Multi-shot</strong> <code>op: (x, k) ~&gt; e</code> — the op <strong>suspends</strong>: eval unwinds to the <code>handle</code> driver, which invokes the clause with <code>(payload, resume)</code>. The <strong>clause&#39;s result is the <code>handle</code> result</strong> (standard deep-handler reading — <code>resume</code> already folds in the <code>return</code> clause).</li></ul><p><code>resume(x)</code>:</p><ul><li>re-runs the body under the same handler with the journal prefix <code>entries[0..i] ++ [x]</code> (entries are <code>(op, result)</code> pairs in perform order; replay validates the op name at each index and errors on a nondeterministic sequence);</li><li>returns the body&#39;s completed value — applying the handler&#39;s <code>return:</code> clause when present;</li><li>a suspension <em>inside</em> a re-run invokes the covering clause again and its result becomes this <code>resume</code>&#39;s return value — so <code>flat_map(opts, o ~&gt; resume(o))</code> collects one result per option (delimited <code>shift</code>/<code>reset</code> semantics: <code>k</code> returns the final answer of the delimited computation, not the perform-site value).</li></ul><p><code>resume</code> is a <strong>copyable, non-consumable</strong> value. One-shot is a style (call it once), not a type — <code>k</code> may be called zero or more times. A consumable <code>k</code> would rule out <code>choose</code>/<code>yield</code> and adds no safety under replay (a second call simply re-runs again).</p><p><strong>Escape</strong>: allowed and well-defined for pure bodies — <code>resume</code> is a function of the delimited continuation, so calling it after <code>handle</code> returns re-runs the body. Caveats (documented, not enforced): host calls and <code>assign</code> writes inside the body prefix re-execute on every <code>resume</code> call; the body evals on an env snapshot, so <code>assign</code> writes to enclosing scopes do not escape the handled body (an isolation property replay <em>requires</em>, not just permits).</p><p><strong>Coverage</strong>: <code>resume</code> mints only when the op&#39;s covering clause takes ≥2 params. Uncovered ops mint residual <code>IO&lt;{op: arg}&gt;</code> data as today; 1-ary clauses take the existing one-shot path.</p><h2 id="mechanism-tree-walk" tabindex="-1">Mechanism (tree-walk) <a class="header-anchor" href="#mechanism-tree-walk" aria-label="Permalink to “Mechanism (tree-walk)”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handle &lt;body&gt; with &lt;handler&gt;</span></span>
<span class="line"><span>  → eval impl_ → handler_val</span></span>
<span class="line"><span>  → if any clause is ≥2-ary:  journalize + drive</span></span>
<span class="line"><span>      push journal {body, incoming, entry_env, handler, ast, entries:[], cursor:0}</span></span>
<span class="line"><span>      push handler</span></span>
<span class="line"><span>      eval body</span></span>
<span class="line"><span>        perform(op, arg) [call_host/call_host_fn intercept]:</span></span>
<span class="line"><span>          innermost journal whose handler covers \`op\` with ≥2-ary impl:</span></span>
<span class="line"><span>            i = cursor++</span></span>
<span class="line"><span>            i &lt; entries.len()  → return entries[i].result   (replay)</span></span>
<span class="line"><span>            else               → record suspension{i, op, arg, journal}</span></span>
<span class="line"><span>                                 → Err(LangError::Suspended{id})</span></span>
<span class="line"><span>        LangError::Suspended{id} at driver:</span></span>
<span class="line"><span>          clause = handler.impl[op];  k = {&quot;__resume__&quot;: id}</span></span>
<span class="line"><span>          return apply(clause, [arg, k])</span></span>
<span class="line"><span>  → else: today&#39;s path (guard + eval + interpret_io_former + carried handler)</span></span></code></pre></div><ul><li><strong><code>resume</code> value</strong>: <code>{&quot;__resume__&quot;: &lt;id&gt;}</code> object; <code>apply_app</code> intercepts it before the dispatch-object/<code>__term__</code>/Arrow arms and drives a re-run. Same reserved-key convention as <code>__term__</code>/<code>__arr__</code>.</li><li><strong>State lives in thread-locals</strong>, not on the engine: <code>TreeWalkCallable</code> (host fns calling arrows — e.g. <code>list.flat_map</code>&#39;s callback) constructs a <em>fresh</em> <code>TreeWalkEngine</code>, so journal/suspension state on <code>self</code> would be invisible to <code>resume</code> invoked inside the clause&#39;s callbacks. <code>RESUME_JOURNALS</code> (stack, innermost-last) + <code>RESUME_SUSPENSIONS</code> (id → suspension) + <code>RESUME_NEXT_ID</code>.</li><li><strong><code>Term::Op</code>/<code>dispatch_op</code></strong>: a ≥2-ary impl covering the op under an active journal suspends identically (dead code today — 2-ary impls applied with one arg error on arity).</li><li><strong>Suspension ownership</strong>: a <code>Suspended{id}</code> records its journal; a driver catches only suspensions belonging to <em>its</em> journal — outer suspensions propagate through nested handles untouched.</li></ul><h2 id="known-limits-prototype" tabindex="-1">Known limits (prototype) <a class="header-anchor" href="#known-limits-prototype" aria-label="Permalink to “Known limits (prototype)”">​</a></h2><ul><li><strong>Deterministic bodies only</strong>: replay assumes the op sequence is stable across runs. Non-op side effects (host calls, <code>assign</code>, <code>enclosing_updated</code> feedback wires) re-execute per <code>resume</code> call — an error message names the op/index on replay mismatch, but mutation in the prefix is the caller&#39;s responsibility.</li><li><strong>Host-callback boundary</strong>: a suspension crossing <code>call_value</code> (<code>fn.map</code> of a performing arrow, etc.) stringifies at the <code>EvalError</code> boundary — <code>resume</code> <em>calls</em> inside callbacks work (they drive locally); arrows that <em>perform</em> inside host callbacks do not suspend through the callback.</li><li><strong><code>.hnl</code> <code>try</code>/error-catch</strong> can swallow <code>LangError::Suspended</code> like any error — same caveat as any error-channel control flow; the <code>Handle</code> arm&#39;s impl-fallback catch is audited to re-propagate.</li><li><strong><code>handle_dyn</code> shared op</strong> carries the compiled-backend path: the cranelift engine overrides <code>NativeOpCtx::run_delimited</code> to install a journal when the handler has a ≥2-ary clause, and intercepts <code>perform</code> / <code>arr &lt;op&gt;</code> before one-shot dispatch. Because cranelift arrow values run in the tree-walk interpreter (<code>apply_value_treewalk</code>), a <code>resume</code> called from inside a clause body crosses engines: the suspending engine registers an engine-neutral driver (<code>native_ops::register_resumption_driver</code>) and every engine&#39;s <code>__resume__</code> seam consults that shared table before its own. Cranelift recovers <code>&amp;mut EvalCtx</code> from a thread-local installed for the duration of the clause application — a <code>resume</code> that <em>escapes</em> the clause and is called with no cranelift evaluation active errors instead of re-running.</li><li><strong>Escape</strong> is supported while the eval is live: a clause may return the resumption value and the caller may apply it (<code>k</code> is first-class and copyable). The <em>cross-engine</em> bridge needs a cranelift evaluation to be active, so a <code>resume</code> applied later from a host callback with no cranelift eval in progress errors instead of re-running.</li><li><strong>Eager sibling evaluation</strong> (compiled backends): a body keeps evaluating sibling nodes after the first suspension (the deferred-error channel), so the journal freezes on the first suspension, re-raising it for later <code>perform</code>s in the same run — the cursor does not advance past it and the first suspension stays the run&#39;s result. Cranelift&#39;s codegen also unwinds immediately on a pending suspension at operand and <code>Seq</code> boundaries, so this is a belt-and-braces guard.</li><li><strong><code>perform</code> inside a <code>rec</code>/loop fixpoint region</strong> is unsupported — not because the suspension is lost (the fixpoint now unwinds to the driver instead of skipping the binding), but because a fixpoint re-evaluates its statements once per pass, so the same <code>perform</code> would consume a new journal entry each pass and replay can never converge. Keep performing ops outside <code>rec</code>/loop desugars.</li><li><strong>Table lifecycle</strong>: suspensions and cross-engine drivers are retained for the duration of an eval (that is what makes an escaped <code>resume</code> callable) and reclaimed by <code>ResumeTableScope</code> when the outermost eval on the thread returns.</li></ul><h2 id="bytecode-cranelift-capture-strategy" tabindex="-1">Bytecode / Cranelift capture strategy <a class="header-anchor" href="#bytecode-cranelift-capture-strategy" aria-label="Permalink to “Bytecode / Cranelift capture strategy”">​</a></h2><p>The bytecode engine implements the replay driver natively (its <code>apply_app</code> re-enters the VM, so journal and clauses stay in one engine). Cranelift takes the replay path through the shared <code>handle_dyn</code> hook + the cross-engine driver bridge described above; a frame-serialization or copyable-stack capture remains a later option if profiling demands it:</p><ol><li><strong>Frame serialization</strong>: the bytecode VM&#39;s eval already materializes activation state per arrow application; capture = serialize the live frame chain at <code>perform</code> into a <code>Resume</code> value, restore on apply. Cost: every <code>Op</code>/<code>call</code> needs a snapshot point.</li><li><strong>Segmented stacks</strong>: the <code>stacker</code> growable-stack seam already segments the native stack; a <code>corosensei</code>-style stackful-coroutine crate gives one-shot for free, but multi-shot still needs a copyable-stack implementation (fork the segment chain). Replay avoids all of it — recommend replay first for parity, frame serialization later if profiling demands it.</li></ol><h2 id="correspondence-sanada-→-this-design" tabindex="-1">Correspondence (Sanada → this design) <a class="header-anchor" href="#correspondence-sanada-→-this-design" aria-label="Permalink to “Correspondence (Sanada → this design)”">​</a></h2><table tabindex="0"><thead><tr><th>Sanada</th><th>handl + this design</th></tr></thead><tbody><tr><td>clause continuation <code>k</code></td><td><code>resume</code> — a <code>{&quot;__resume__&quot;: id}</code> value</td></tr><tr><td><code>k</code> invoked once (one-shot)</td><td>1-ary clause sugar <code>(x) ~&gt; e</code> ≡ <code>(x,k) ~&gt; k(e)</code></td></tr><tr><td><code>k</code> multi-shot</td><td><code>resume</code> reusable — replay makes it copyable</td></tr><tr><td>handler = algebra homomorphism</td><td>clause result = handle result; <code>return:</code> clause = unit map</td></tr><tr><td>prompt/delimiter</td><td><code>handle</code> boundary = <code>reset</code>; <code>perform</code> = <code>shift</code></td></tr></tbody></table>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};